// Certificates — reads the server-issued completion certificate for a course
// and renders a download CTA. Certificates are generated by the
// onCertificateProgress Cloud Function once every module is complete; this
// module only reads users/{uid}/certificates/{slug}.

import { auth, db, firebaseReady } from './firebase.js';
import {
  doc, getDoc
} from 'https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js';

/** Returns the cert record { slug, courseTitle, downloadUrl, ... } or null. */
export async function loadCertificate(slug) {
  if (!firebaseReady || !auth || !auth.currentUser || !slug) return null;
  try {
    const snap = await getDoc(doc(db, 'users', auth.currentUser.uid, 'certificates', slug));
    return snap.exists() ? snap.data() : null;
  } catch (e) {
    console.warn('[certificates] load failed', e);
    return null;
  }
}

// Renders a "Download Certificate" CTA into `container` if a cert exists for the
// slug. Safe to call repeatedly (clears prior content). The cert may take a
// moment to appear after finishing (the trigger runs server-side), so callers
// can re-invoke after completion.
export async function renderCertCta(slug, container) {
  if (!container) return;
  const cert = await loadCertificate(slug);
  if (!cert) return;
  const url = cert.downloadUrl;
  container.innerHTML = url
    ? `<a class="btn btn-success" href="${url}" target="_blank" rel="noopener" download>🎓 Download Certificate</a>`
    : `<span class="pill pill-ok">🎓 Certificate issued — check your email</span>`;
}
